from collections import Counter
def fill_boxes(g, fill=4):
    h,w=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    bg=cnt.most_common(1)[0][0]
    F=[c for c in cnt if c!=bg][0]
    g=[r[:] for r in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=F: continue
            for rb in range(r+1,h):
                for cb in range(c+1,w):
                    if g[rb][c]==g[r][cb]==g[rb][cb]==F:
                        # full border?
                        if all(g[r][j]==F and g[rb][j]==F for j in range(c,cb+1)) and \
                           all(g[i][c]==F and g[i][cb]==F for i in range(r,rb+1)):
                            if all(g[i][j]==bg for i in range(r+1,rb) for j in range(c+1,cb)):
                                for i in range(r+1,rb):
                                    for j in range(c+1,cb): g[i][j]=fill
    return g

